xm2 Vout N003 N004 0 sky130_fd_pr__nfet_01v8 w={W_xm2} l={L_xm2}
xm1 N001 N002 N004 0 sky130_fd_pr__nfet_01v8 w={W_xm1} l={L_xm1}
